using System;using System.IO;using System.Windows;using System.Windows.Controls;using DualSteam.UI;
public sealed class SetupWizard:Window {
 public string SteamPath,DataPath;
 public SetupWizard(string detected){Title="Set up Second Steam";Width=640;Height=560;MinWidth=580;WindowStartupLocation=WindowStartupLocation.CenterOwner;ResizeMode=ResizeMode.CanResize;MinHeight=460;Theme.Bind(this,BackgroundProperty,"bg.window");Theme.Bind(this,ForegroundProperty,"text.primary");Theme.Bind(this,FontFamilyProperty,"Font.App");var body=new StackPanel{Margin=new Thickness(28)};body.Children.Add(Ui.Text("Set up Second Steam",24,"text.primary",true));var intro=Ui.Text("Choose your installed Steam and an empty folder. Setup creates a separate standard Windows account and profile. It does not copy your Steam login or games.");intro.Margin=new Thickness(0,12,0,24);body.Children.Add(intro);
  body.Children.Add(Ui.Text("Main Steam executable",13,"text.primary",true));var steam=new TextBox{Text=detected,Margin=new Thickness(0,8,0,8),Padding=new Thickness(8)};body.Children.Add(steam);body.Children.Add(Ui.Button("Browse for Steam",false,()=>{var d=new Microsoft.Win32.OpenFileDialog{Filter="Steam client|steam.exe",Title="Find the installed Steam client"};if(d.ShowDialog(this)==true)steam.Text=d.FileName;}));
  var label=Ui.Text("Second Steam data folder",13,"text.primary",true);label.Margin=new Thickness(0,20,0,0);body.Children.Add(label);var data=new TextBox{Text=SetupService.SuggestedRoot,Margin=new Thickness(0,8,0,8),Padding=new Thickness(8)};body.Children.Add(data);body.Children.Add(Ui.Button("Choose data folder",false,()=>{using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="Choose an empty folder for Second Steam",SelectedPath=Path.GetDirectoryName(data.Text)})if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK)data.Text=d.SelectedPath;}));
  var note=Ui.Text("Windows will ask for administrator permission once to create the account. Steam then downloads its clean client and asks you to sign in to the second account. Windows retains a small initial profile backup on the system drive.",12,"text.muted");note.Margin=new Thickness(0,20,0,16);body.Children.Add(note);var actions=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right};var cancel=Ui.Button("Cancel",false,()=>DialogResult=false);cancel.Margin=new Thickness(0,0,8,0);actions.Children.Add(cancel);actions.Children.Add(Ui.Button("Set up Second Steam",true,()=>{try{SetupService.Validate(steam.Text,data.Text);SteamPath=steam.Text;DataPath=data.Text;DialogResult=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Check setup",MessageBoxButton.OK,MessageBoxImage.Information);}}));body.Children.Add(actions);Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled};
 }
}
